        in_char = inp[j] if j < len(inp) else " "
        out_char = out[j] if j < len(out) else " "
        if in_char != out_char:
            print(f"{j}({in_char}->{out_char}) ", end="")
        else:
            print(f"{j}({in_char}) ", end="")
    print()

